using Backend.Persistence.Domain; using Microsoft.EntityFrameworkCore; namespace Backend.Persistence.Data;
public sealed class AppDbContext(DbContextOptions<AppDbContext> o):DbContext(o){public DbSet<Client> Clients=>Set<Client>(); public DbSet<Workspace> Workspaces=>Set<Workspace>(); public DbSet<Assessment> Assessments=>Set<Assessment>(); public DbSet<Spec> Specs=>Set<Spec>(); public DbSet<PipelineInstance> PipelineInstances=>Set<PipelineInstance>(); public DbSet<PhaseTransition> PhaseTransitions=>Set<PhaseTransition>(); public DbSet<PerfilCredential> PerfilCredentials=>Set<PerfilCredential>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<Client>(e=>{e.ToTable("client");e.HasKey(x=>x.Id);e.Property(x=>x.Name).HasMaxLength(200).IsRequired();}); b.Entity<Workspace>(e=>{e.ToTable("workspace");e.HasKey(x=>x.Id);e.Property(x=>x.TenantId).HasDefaultValue("default");e.Property(x=>x.SpecsPath).HasDefaultValue("specs/");e.Property(x=>x.AdoWorkItemType).HasDefaultValue("User Story");e.Property(x=>x.Platform).HasConversion<string>();e.Property(x=>x.Status).HasConversion<string>();e.HasIndex(x=>x.Slug).IsUnique();e.HasOne(x=>x.Client).WithMany(x=>x.Workspaces).HasForeignKey(x=>x.ClientId).OnDelete(DeleteBehavior.SetNull);}); b.Entity<Assessment>(e=>{e.ToTable("assessment");e.HasKey(x=>x.Id);e.Property(x=>x.Status).HasConversion<string>();e.HasOne(x=>x.Workspace).WithMany(x=>x.Assessments).HasForeignKey(x=>x.WorkspaceId).OnDelete(DeleteBehavior.Cascade);e.HasOne(x=>x.Client).WithMany(x=>x.Assessments).HasForeignKey(x=>x.ClientId).OnDelete(DeleteBehavior.Restrict);}); b.Entity<Spec>(e=>{e.ToTable("spec");e.HasKey(x=>x.Id);e.HasIndex(x=>new{x.WorkspaceId,x.Path}).IsUnique();e.HasOne(x=>x.Workspace).WithMany(x=>x.Specs).HasForeignKey(x=>x.WorkspaceId).OnDelete(DeleteBehavior.Cascade);}); b.Entity<PipelineInstance>(e=>{e.ToTable("pipeline_instance");e.HasKey(x=>x.Id);e.Property(x=>x.FaseAtual).HasConversion<string>();e.Property(x=>x.GateStatus).HasConversion<string>();e.HasIndex(x=>new{x.WorkspaceId,x.ExternalRef}).IsUnique();e.HasOne(x=>x.Workspace).WithMany(x=>x.PipelineInstances).HasForeignKey(x=>x.WorkspaceId).OnDelete(DeleteBehavior.Cascade);e.HasOne(x=>x.Spec).WithMany(x=>x.PipelineInstances).HasForeignKey(x=>x.SpecId).OnDelete(DeleteBehavior.SetNull);}); b.Entity<PhaseTransition>(e=>{e.ToTable("phase_transition");e.HasKey(x=>x.Id);e.Property(x=>x.Fase).HasConversion<string>();e.HasOne(x=>x.PipelineInstance).WithMany(x=>x.PhaseTransitions).HasForeignKey(x=>x.PipelineInstanceId).OnDelete(DeleteBehavior.Cascade);}); b.Entity<PerfilCredential>(e=>{e.ToTable("perfil_credential");e.HasKey(x=>x.Id);e.Property(x=>x.Perfil).HasConversion<string>();e.Property(x=>x.Status).HasConversion<string>();e.HasOne(x=>x.Workspace).WithMany(x=>x.PerfilCredentials).HasForeignKey(x=>x.WorkspaceId).OnDelete(DeleteBehavior.Cascade);});}}
